Tenant.local:
send LeaseEnded to Landlord;
send ForwardingAddress to Landlord;
offer {
  receive DepositReturned from Landlord;
} or {
  receive DeductionsItemized from Landlord;
  receive DepositReturned from Landlord;
}

Landlord.local:
receive LeaseEnded from Tenant;
receive ForwardingAddress from Tenant;
select {
  send DepositReturned to Tenant;
} or {
  send DeductionsItemized to Tenant;
  send DepositReturned to Tenant;
}

